import { useEffect, useState } from "react";

/**
 * Tracks the user's `prefers-reduced-motion` setting.
 *
 * CSS transitions/animations are already neutralized globally by the
 * reduced-motion block in `utilities.css`; use this hook to gate JS-driven
 * motion that CSS can't reach -- e.g. `scrollTo`/`scrollIntoView({ behavior:
 * 'smooth' })` and swipe slide animations. Returns `true` when the user prefers
 * reduced motion.
 */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  return reduced;
}
